function frame(){
 update();ctx.clearRect(0,0,W,H);
 if(mode==='title')drawTitle();else if(mode==='play'){drawWorld();hud();drawTouch();if(toastTime>0){rounded(130,232,220,21,5,'#233a42e8');text(toast,240,243,8,'#fff0c7','center')}}else if(mode==='town')drawTown();else if(mode==='lost')drawLost();else drawEnding();
