function toGamePoint(e){let r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*W/r.width,y:(e.clientY-r.top)*H/r.height}}
function pressAt(x,y){
 if(mode==='title'){
  if(y>105&&y<193){animalIndex=Math.max(0,Math.min(2,Math.floor((x-54)/126)));return}
  if(y>211){startRun();return}
 }
 if(mode==='town'){
  if(x>=267&&x<=462&&y>=125&&y<=216){let i=Math.floor((y-128)/27);if(i===0)buy('boots',8);if(i===1)buy('umbrella',10);if(i===2)buy('pack',12);return}
  if(y>218){startNext();return}
 }
 if(mode==='lost'){if(y>183){startRun();return}}
 if(mode==='ending'){startRun();return}
 if(mode==='play'){
  if(x<100&&y>190){if(x<50)keys.add('touchleft');else keys.add('touchright');return}
  if(x>380&&y>190){if(x<430)doJump();else explore();return}
  if(y<100&&x>160&&x<320)explore();
 }
}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.setPointerCapture(e.pointerId);pointer.down=true;let p=toGamePoint(e);pointer.x=p.x;pointer.y=p.y;pressAt(p.x,p.y)});
canvas.addEventListener('pointermove',e=>{let p=toGamePoint(e);pointer.x=p.x;pointer.y=p.y;if(pointer.down&&mode==='play'&&p.y>190&&p.x<100){keys.delete('touchleft');keys.delete('touchright');keys.add(p.x<50?'touchleft':'touchright')}});
function releasePointer(){pointer.down=false;keys.delete('touchleft');keys.delete('touchright')}
canvas.addEventListener('pointerup',releasePointer);canvas.addEventListener('pointercancel',releasePointer);
